DO $test$
DECLARE r jsonb;
BEGIN
 r:=fn_driver_arrive_v2('71000000-0000-0000-0000-000000000001','77000000-0000-0000-0000-000000000006',0,4,5,3,
  '73000000-0000-0000-0000-000000000002','7a000000-0000-4000-8000-000000000001','7b000000-0000-4000-8000-000000000001');
 IF r->>'reason_code'<>'STOP_NOT_NEXT_IN_ROUTE' THEN RAISE EXCEPTION 'out-of-order arrival accepted:%',r; END IF;
 r:=fn_driver_arrive_v2('71000000-0000-0000-0000-000000000001','77000000-0000-0000-0000-000000000005',0,4,5,3,
  '73000000-0000-0000-0000-000000000002','7a000000-0000-4000-8000-000000000002','7b000000-0000-4000-8000-000000000002');
 IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'next arrival rejected:%',r; END IF;
 r:=fn_driver_arrive_v2('71000000-0000-0000-0000-000000000001','77000000-0000-0000-0000-000000000005',0,4,5,3,
  '73000000-0000-0000-0000-000000000002','7a000000-0000-4000-8000-000000000002','7b000000-0000-4000-8000-000000000099');
 IF r->>'idempotent_replay'<>'true' THEN RAISE EXCEPTION 'arrival replay failed:%',r; END IF;
 PERFORM set_config('mise.test_multi_order_failpoint','after_cancel_stops',true);
 BEGIN
  PERFORM fn_dispatch_cancel_order_v3('71000000-0000-0000-0000-000000000001','76000000-0000-0000-0000-000000000001',4,7,9,12,10,
   gen_random_uuid(),'7a000000-0000-4000-8000-000000000003','CUSTOMER_CANCELLED');
  RAISE EXCEPTION 'cancel failpoint did not fire';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'T12_FAILPOINT_AFTER_CANCEL_STOPS' THEN RAISE; END IF; END;
 PERFORM set_config('mise.test_multi_order_failpoint','',true);
 IF (SELECT state FROM dispatch_offer_assignments WHERE id='79000000-0000-0000-0000-000000000001')<>'in_progress'
  OR (SELECT state FROM mise_delivery_batch_stops WHERE id='77000000-0000-0000-0000-000000000002')<>'pending'
 THEN RAISE EXCEPTION 'cancel crash left partial state'; END IF;
 r:=fn_dispatch_cancel_order_v3('71000000-0000-0000-0000-000000000001','76000000-0000-0000-0000-000000000001',4,7,9,12,10,
  gen_random_uuid(),'7a000000-0000-4000-8000-000000000004','CUSTOMER_CANCELLED');
 IF r->>'state'<>'route_pending' OR r->>'remaining_orders'<>'1'
  OR (SELECT state FROM dispatch_offer_assignments WHERE id='79000000-0000-0000-0000-000000000002')<>'in_progress'
  OR (SELECT state FROM mise_delivery_batch_stops WHERE id='77000000-0000-0000-0000-000000000004')<>'pending'
  OR (SELECT state FROM mise_delivery_batches WHERE id='75000000-0000-0000-0000-000000000001')<>'in_progress'
  OR (SELECT route_version FROM mise_delivery_batches WHERE id='75000000-0000-0000-0000-000000000001')<>13
  OR (SELECT current_capacity FROM mise_drivers WHERE id='73000000-0000-0000-0000-000000000001')<>1
  OR (SELECT state FROM driver_departure_workflows_v2 WHERE batch_id='75000000-0000-0000-0000-000000000001')<>'route_pending'
 THEN RAISE EXCEPTION 'order-scoped cancellation damaged remaining trip:%',r; END IF;
 r:=fn_dispatch_cancel_order_v3('71000000-0000-0000-0000-000000000001','76000000-0000-0000-0000-000000000002',6,8,10,13,11,
  gen_random_uuid(),'7a000000-0000-4000-8000-000000000005','LAST_ORDER_CANCELLED');
 IF r->>'state'<>'trip_cancelled' OR r->>'remaining_orders'<>'0'
  OR (SELECT state FROM mise_delivery_batches WHERE id='75000000-0000-0000-0000-000000000001')<>'cancelled'
  OR (SELECT state FROM mise_drivers WHERE id='73000000-0000-0000-0000-000000000001')<>'returning'
  OR (SELECT current_capacity FROM mise_drivers WHERE id='73000000-0000-0000-0000-000000000001')<>0
 THEN RAISE EXCEPTION 'empty trip was not closed:%',r; END IF;
END $test$;
\echo 'T12 multi-order cancel and strict arrival: PASS'
